mail:[{from:'Bente Lauritzen',to:'Thomas Ebbesen; Sofie Krag',time:'21:58',subject:'I to. Nu.',body:'Jeg har sammenholdt loggen over, hvem der åbnede de lækkede filer, med listen over, hvem der havde adgang. Der er kun to navne tilbage: jeres.\n\nKom op til mig. Jeg vil høre jeres forklaring, før jeg går til ledelsen i morgen.\n\nB.'},{from:'Lisbeth Moe',to:'Bente Lauritzen',time:'16:12',subject:'Vedr. fremtiden',body:'Kære Bente. Lad os tage en snak efter weekenden om din rolle fremover. Venlig hilsen Lisbeth'},{from:'Kasper Vang',to:'Bente Lauritzen',time:'14:30',subject:'Igen?!',body:'Min historie om havnen stod i Morgenposten i dag. Det er tredje gang. Find ham.'}],
